exercises.solution:
String jvm = System.getProperty("java.vm.version");
String jdk = System.getProperty("java.version");
System.out.println("JVM: " + jvm);
System.out.println("JDK: " + jdk);
System.out.println("Takie same? " + jvm.equals(jdk));

System.out.println("Wersja Java: " + System.getProperty("java.version"));
System.out.println("Producent: " + System.getProperty("java.vendor"));
System.out.println("System: " + System.getProperty("os.name"));
System.out.println("Wersja systemu: " + System.getProperty("os.version"));
System.out.println("Uzytkownik: " + System.getProperty("user.name"));

String version = System.getProperty("java.version");
System.out.println("Wersja: " + version);
System.out.println("To Java 21? " + version.startsWith("21"));

int[] licznik = {0};
System.getProperties().forEach((klucz, wartosc) -> {
    if (klucz.toString().startsWith("java.")) {
        licznik[0]++;
    }
});
System.out.println("Liczba wlasciwosci java.*: " + licznik[0]);

Runtime runtime = Runtime.getRuntime();
System.out.println("Procesory: " + runtime.availableProcessors());
System.out.println("Pamiec calkowita: " + runtime.totalMemory());
System.out.println("Pamiec wolna: " + runtime.freeMemory());

String javaHome = System.getProperty("java.home").toLowerCase();
if (javaHome.contains("jdk")) {
    System.out.println("Uzywasz JDK");
} else if (javaHome.contains("jre")) {
    System.out.println("Uzywasz JRE");
} else {
    System.out.println("Nie udalo sie jednoznacznie okreslic (sciezka: " + javaHome + ")");
}

System.out.println("==================== SRODOWISKO JAVA ====================");
System.out.println("Wersja Java: " + System.getProperty("java.version"));
System.out.println("Producent JVM: " + System.getProperty("java.vm.vendor"));
System.out.println("System operacyjny: " + System.getProperty("os.name"));
System.out.println("Architektura: " + System.getProperty("os.arch"));
System.out.println("Katalog domowy: " + System.getProperty("user.home"));
System.out.println("=".repeat(59));

String javaVersion = System.getProperty("java.version");
String vmVersion = System.getProperty("java.vm.version");
System.out.println("java.version = " + javaVersion);
System.out.println("java.vm.version = " + vmVersion);
System.out.println("Identyczne? " + javaVersion.equals(vmVersion));

Runtime runtime = Runtime.getRuntime();
long maxMb = runtime.maxMemory() / (1024 * 1024);
long totalMb = runtime.totalMemory() / (1024 * 1024);
long freeMb = runtime.freeMemory() / (1024 * 1024);
System.out.println("Max: " + maxMb + " MB");
System.out.println("Total: " + totalMb + " MB");
System.out.println("Free: " + freeMb + " MB");

java.util.List<String> klucze = new java.util.ArrayList<>(System.getProperties().stringPropertyNames());
java.util.Collections.sort(klucze);
for (String klucz : klucze) {
    System.out.println(klucz + " = " + System.getProperty(klucz));
}

String specJava = System.getProperty("java.specification.version");
String specVm = System.getProperty("java.vm.specification.version");
System.out.println("Specyfikacja Java: " + specJava);
System.out.println("Specyfikacja JVM: " + specVm);
System.out.println("Rowne? " + specJava.equals(specVm));

String version = System.getProperty("java.version");
int dotIndex = version.indexOf('.');
int majorVersion = dotIndex == -1 ? Integer.parseInt(version) : Integer.parseInt(version.substring(0, dotIndex));
System.out.println("1. Wersja Java: " + version + " (LTS 17+? " + (majorVersion >= 17) + ")");
System.out.println("2. System: " + System.getProperty("os.name") + ", architektura: " + System.getProperty("os.arch"));
long memMb = Runtime.getRuntime().totalMemory() / (1024 * 1024);
System.out.println("3. Pamiec JVM: " + memMb + " MB");
System.out.println("4. Procesory: " + Runtime.getRuntime().availableProcessors());
System.out.println("5. Katalog domowy: " + System.getProperty("user.home"));
